-- Données initiales sans NULL, comme dans l’énoncé.
SELECT animal FROM zoo GROUP BY animal
HAVING COUNT(DISTINCT nom)>1 OR COUNT(DISTINCT annee_naissance)>1
 OR COUNT(DISTINCT espece)>1 OR COUNT(DISTINCT emplacement)>1;
SELECT nom,espece FROM zoo GROUP BY nom,espece
HAVING COUNT(DISTINCT animal)>1;
SELECT espece FROM zoo GROUP BY espece
HAVING COUNT(DISTINCT origine)>1 OR COUNT(DISTINCT classe)>1;
SELECT gardien FROM zoo GROUP BY gardien
HAVING COUNT(DISTINCT prenom)>1 OR COUNT(DISTINCT salaire)>1;
SELECT emplacement FROM zoo GROUP BY emplacement
HAVING COUNT(DISTINCT surface)>1 OR COUNT(DISTINCT type_empl)>1
 OR COUNT(DISTINCT gardien)>1;
SELECT type_empl FROM zoo GROUP BY type_empl
HAVING COUNT(DISTINCT libelle_empl)>1;
SELECT animal,emplacement FROM zoo GROUP BY animal,emplacement
HAVING COUNT(DISTINCT surface)>1;

Exemple exécutable DuckDB pour la règle Espece→Origine,Classe :
WITH reference AS (
 SELECT espece,origine,classe,
 ROW_NUMBER() OVER (PARTITION BY espece ORDER BY animal) AS rn
 FROM zoo
)
UPDATE zoo AS z SET origine=r.origine,classe=r.classe
FROM reference r WHERE r.rn=1 AND z.espece=r.espece;

Même méthode complète à appliquer aux autres déterminants :
- PARTITION BY animal : cibles nom,annee_naissance,espece,emplacement ;
- PARTITION BY nom,espece : cible animal ;
- PARTITION BY gardien : cibles prenom,salaire ;
- PARTITION BY emplacement : cibles surface,type_empl,gardien ;
- PARTITION BY type_empl : cible libelle_empl.
La règle Animal,Emplacement→Surface n’a pas de correction autonome après Emplacement→Surface.
Pour chaque étape : calculer la ligne de référence, prévisualiser les modifications, puis affecter toutes ses cibles aux lignes de même source. Réexécuter les contrôles après les changements de sources (animal,nom,espece,emplacement,gardien,type_empl), car ils peuvent réunir des groupes auparavant distincts. Des doublons de numéro animal après correction de Nom,Espece→Animal exigent de fusionner leurs données sous cette même règle et de dédupliquer avant une PK. Si plusieurs lignes du plus petit animal sont incompatibles, la consigne ne les départage pas : il faut une décision métier explicite. Sans les données originales, on ne peut pas fournir les valeurs constantes de leurs UPDATE.

Autres UPDATE explicites (à prévisualiser et exécuter sur les données incohérentes avant les contrôles finaux) :

WITH reference AS (
 SELECT animal,nom,annee_naissance,espece,emplacement,
 ROW_NUMBER() OVER (PARTITION BY animal ORDER BY animal) AS rn
 FROM zoo
)
UPDATE zoo AS z SET nom=r.nom,annee_naissance=r.annee_naissance,espece=r.espece,emplacement=r.emplacement
FROM reference r WHERE r.rn=1 AND z.animal=r.animal;

WITH reference AS (
 SELECT nom,espece,animal,
 ROW_NUMBER() OVER (PARTITION BY nom,espece ORDER BY animal) AS rn
 FROM zoo
)
UPDATE zoo AS z SET animal=r.animal
FROM reference r WHERE r.rn=1 AND z.nom=r.nom AND z.espece=r.espece;

WITH reference AS (
 SELECT gardien,prenom,salaire,
 ROW_NUMBER() OVER (PARTITION BY gardien ORDER BY animal) AS rn
 FROM zoo
)
UPDATE zoo AS z SET prenom=r.prenom,salaire=r.salaire
FROM reference r WHERE r.rn=1 AND z.gardien=r.gardien;

WITH reference AS (
 SELECT emplacement,surface,type_empl,gardien,
 ROW_NUMBER() OVER (PARTITION BY emplacement ORDER BY animal) AS rn
 FROM zoo
)
UPDATE zoo AS z SET surface=r.surface,type_empl=r.type_empl,gardien=r.gardien
FROM reference r WHERE r.rn=1 AND z.emplacement=r.emplacement;

WITH reference AS (
 SELECT type_empl,libelle_empl,
 ROW_NUMBER() OVER (PARTITION BY type_empl ORDER BY animal) AS rn
 FROM zoo
)
UPDATE zoo AS z SET libelle_empl=r.libelle_empl
FROM reference r WHERE r.rn=1 AND z.type_empl=r.type_empl;

Animal et Nom,Espece sont les deux clés universelles. Après retrait de la DF redondante, on groupe par source, fusionne ici les groupes Animal et Nom,Espece, puis crée Animal, Espece, Gardien, Emplacement, Type_empl. Pas d’inclusion à supprimer ; Animal contient déjà une clé universelle. Chaque source de DF devient une clé d’une table, les tables sont même BCNF. Le choix NOT NULL ci-dessous conserve la politique de données complètes de l’énoncé ; la clé alternative demande NOT NULL sur nom et espece.

CREATE TABLE espece (
 espece VARCHAR(30) PRIMARY KEY,
 origine VARCHAR(30) NOT NULL,
 classe VARCHAR(30) NOT NULL
);
CREATE TABLE gardien (
 gardien VARCHAR(40) PRIMARY KEY,
 prenom VARCHAR(40) NOT NULL,
 salaire DECIMAL(10,2) NOT NULL
);
CREATE TABLE type_empl (
 type_empl INTEGER PRIMARY KEY,
 libelle_empl VARCHAR(40) NOT NULL
);
CREATE TABLE emplacement (
 emplacement INTEGER PRIMARY KEY,
 surface INTEGER NOT NULL,
 type_empl INTEGER NOT NULL REFERENCES type_empl(type_empl),
 gardien VARCHAR(40) NOT NULL REFERENCES gardien(gardien)
);
CREATE TABLE animal (
 animal INTEGER PRIMARY KEY,
 nom VARCHAR(40) NOT NULL,
 annee_naissance INTEGER NOT NULL,
 espece VARCHAR(30) NOT NULL REFERENCES espece(espece),
 emplacement INTEGER NOT NULL REFERENCES emplacement(emplacement),
 UNIQUE(nom,espece)
);

INSERT INTO espece(espece,origine,classe)
SELECT DISTINCT espece,origine,classe FROM zoo;
INSERT INTO gardien(gardien,prenom,salaire)
SELECT DISTINCT gardien,prenom,salaire FROM zoo;
INSERT INTO type_empl(type_empl,libelle_empl)
SELECT DISTINCT type_empl,libelle_empl FROM zoo;
INSERT INTO emplacement(emplacement,surface,type_empl,gardien)
SELECT DISTINCT emplacement,surface,type_empl,gardien FROM zoo;
INSERT INTO animal(animal,nom,annee_naissance,espece,emplacement)
SELECT DISTINCT animal,nom,annee_naissance,espece,emplacement FROM zoo;

Les trois premières tables sont indépendantes. Emplacement exige gardien et type_empl ; Animal exige espece et emplacement. DISTINCT retire des lignes identiques, mais deux origines différentes pour la même espèce restent deux lignes différentes et feront échouer la PK. Il faut donc contrôler et corriger avant transfert. Dans une vraie migration, utiliser une transaction et comparer la reconstruction au schéma source corrigé avant de supprimer quoi que ce soit.

SELECT gardien FROM zoo GROUP BY gardien
HAVING COUNT(DISTINCT prenom)>1 OR COUNT(DISTINCT salaire)>1
ORDER BY gardien;
